// Addresses: where the physician has lived and where they have worked, and
// the thing credentialing applications actually check.
//
// Every hospital application and every CVO asks for an address history, and
// what they verify is not the list: it is that the list has NO GAPS and covers
// the required lookback, usually five years and sometimes ten. A physician who
// hands over three addresses with four months unaccounted for between two of
// them gets the application sent back, which is a fortnight.
//
// Each row is a Home (lived there) or a Work address (worked there), stored in
// address_history.kind. The gap check is about where the physician LIVED, so it
// reads Home rows only: work addresses overlap homes and each other by nature
// (two hospitals at once is ordinary), so checking them for gaps would only
// raise false alarms. Work rows are listed with their dates and nothing more.
//
// So the list is half the feature and this file is the other half. It is pure,
// so scripts/address-history.test.mjs runs every case in plain node.

/** The two kinds, as stored in address_history.kind. Null or unknown is home. */
export const ADDRESS_KINDS = Object.freeze(["home", "work"]);
export const ADDRESS_KIND_OPTIONS = Object.freeze([
  Object.freeze({ value: "home", label: "Home (lived here)" }),
  Object.freeze({ value: "work", label: "Work (worked here)" }),
]);

/** "work" only when the row says so; anything else, blank included, is home. */
export function addressKind(r) {
  return String(r?.kind ?? "").trim().toLowerCase() === "work" ? "work" : "home";
}
export const isWorkAddress = (r) => addressKind(r) === "work";
export const homeAddresses = (rows = []) => (rows || []).filter((r) => r && !isWorkAddress(r));
export const workAddresses = (rows = []) => (rows || []).filter((r) => r && isWorkAddress(r));

/** Five years is the usual ask; ten appears on some hospital and state forms. */
export const LOOKBACK_YEARS = [5, 10];
export const DEFAULT_LOOKBACK_YEARS = 5;

const DAY = 24 * 60 * 60 * 1000;

/** A date-only value parsed as UTC midnight, or null. Accepts "" and junk. */
export function asDate(v) {
  if (!v) return null;
  const s = String(v).trim();
  if (!/^\d{4}-\d{2}-\d{2}/.test(s)) return null;
  const t = Date.parse(`${s.slice(0, 10)}T00:00:00Z`);
  return Number.isFinite(t) ? new Date(t) : null;
}

export const ymd = (d) => (d ? d.toISOString().slice(0, 10) : "");

/** One line, the way a form wants it. Missing parts are skipped, not padded. */
export function formatAddress(a) {
  const parts = [
    [a?.street, a?.unit].filter(Boolean).join(" "),
    a?.city,
    [a?.state, a?.postalCode].filter(Boolean).join(" "),
    a?.country && String(a.country).trim().toUpperCase() !== "USA" ? a.country : null,
  ].map((p) => String(p ?? "").trim()).filter(Boolean);
  return parts.join(", ");
}

/**
 * Truthy for the row the physician still lives (or works) at. The column is
 * address_history.is_current, so the app key is `isCurrent`. A `current` key
 * (the first version of this form, before it shipped) is still read, and the
 * select's "Yes" as well as a real boolean.
 */
export const isCurrent = (r) => {
  const v = r?.isCurrent ?? r?.current;
  return v === true || /^(yes|true)$/i.test(String(v ?? "").trim());
};

/** One line for a list or an export: the place name first on a work row. */
export function addressLine(a) {
  const where = formatAddress(a);
  const place = isWorkAddress(a) ? String(a?.placeName ?? "").trim() : "";
  return [place, where].filter(Boolean).join(", ");
}

/** "2019-01-01 to Present", the dates as an application wants them. */
export function addressDates(a) {
  const from = String(a?.startDate ?? "").slice(0, 10);
  const to = isCurrent(a) ? "Present" : String(a?.endDate ?? "").slice(0, 10);
  if (!from && !to) return "";
  return `${from || "?"} to ${to || "?"}`;
}

const byStart = (a, b) => String(a?.startDate || "").localeCompare(String(b?.startDate || ""));

/**
 * The export's view: Home then Work, each oldest first, one line per address.
 * [{ kind, label, rows: [{ row, line, dates }] }], empty groups left out.
 */
export function addressGroups(rows = []) {
  const groups = [
    { kind: "home", label: "Home addresses (where you lived)", rows: homeAddresses(rows) },
    { kind: "work", label: "Work addresses (where you worked)", rows: workAddresses(rows) },
  ];
  return groups
    .map((g) => ({ ...g, rows: [...g.rows].sort(byStart).map((r) => ({ row: r, line: addressLine(r) || "Address", dates: addressDates(r) })) }))
    .filter((g) => g.rows.length);
}

/**
 * The periods to check, oldest first.
 *
 * The CURRENT address is a row in this collection like any other, flagged
 * rather than kept on the profile. profiles.address is the mailing address a
 * document gets sent to and is a different question; keeping the history
 * whole in one place means the two cannot drift, and an application asks for
 * one unbroken list ending today.
 */
export function periods(rows = [], { asOf = new Date() } = {}) {
  const out = [];
  for (const r of rows || []) {
    const from = asDate(r?.startDate);
    const cur = isCurrent(r);
    const to = cur ? null : asDate(r?.endDate);
    if (!from && !to && !cur) continue;
    out.push({ id: r?.id ?? null, label: formatAddress(r), from, to, current: cur, row: r });
  }
  void asOf;
  return out.sort((a, b) => {
    const av = a.from ? a.from.getTime() : -Infinity;
    const bv = b.from ? b.from.getTime() : -Infinity;
    return av - bv;
  });
}

/**
 * What is wrong with this history, in the order a reviewer would notice it.
 *
 * Every problem carries the words to fix it rather than a label. "Gap" on its
 * own tells a physician nothing they can act on at 11pm the night before a
 * deadline.
 *
 * `asOf` is injected so the result is testable and does not move under a test
 * that runs at midnight.
 */
export function addressProblems(rows = [], { years = DEFAULT_LOOKBACK_YEARS, asOf = new Date(), graceDays = 1 } = {}) {
  const problems = [];
  // Where the physician lived: work addresses are never checked for gaps.
  const list = periods(homeAddresses(rows), { asOf });

  for (const p of list) {
    if (!p.from) {
      problems.push({ kind: "missing_start", id: p.id,
        text: `${p.label || "An address"} has no move-in date, so it cannot be placed in the history.` });
    }
    if (!p.current && !p.to) {
      problems.push({ kind: "missing_end", id: p.id,
        text: `${p.label || "An address"} has no move-out date. If you still live there, tick Current instead.` });
    }
    if (p.from && p.to && p.to < p.from) {
      problems.push({ kind: "reversed", id: p.id,
        text: `${p.label || "An address"} ends before it starts.` });
    }
    if (p.from && p.from > asOf) {
      problems.push({ kind: "future", id: p.id,
        text: `${p.label || "An address"} starts in the future.` });
    }
  }

  const currents = list.filter((p) => p.current);
  if (currents.length > 1) {
    problems.push({ kind: "many_current",
      text: `${currents.length} home addresses are marked Current. Only one can be where you live now.` });
  }
  if (list.length && !currents.length) {
    problems.push({ kind: "no_current",
      text: "No home address is marked Current, so where you lived does not reach today. Tick Current on the one you live at now." });
  }

  // Gaps and overlaps, between each period and the next.
  const dated = list.filter((p) => p.from);
  for (let i = 0; i < dated.length - 1; i++) {
    const a = dated[i];
    const b = dated[i + 1];
    const aEnd = a.to || (a.current ? asOf : null);
    if (!aEnd) continue;
    const gapDays = Math.round((b.from - aEnd) / DAY);
    if (gapDays > graceDays) {
      problems.push({ kind: "gap", id: b.id, days: gapDays,
        text: `${gapDays} day${gapDays === 1 ? "" : "s"} unaccounted for between ${ymd(aEnd)} and ${ymd(b.from)}. Applications ask for an unbroken history, so add the address you lived at in between.` });
    } else if (gapDays < -graceDays) {
      problems.push({ kind: "overlap", id: b.id, days: -gapDays,
        text: `${-gapDays} day${-gapDays === 1 ? "" : "s"} overlap between ${a.label || "one address"} and ${b.label || "the next"}. That is fine if you genuinely held both, and a typo otherwise.` });
    }
  }

  // Does it reach back far enough?
  const earliest = dated.length ? dated[0].from : null;
  const need = new Date(asOf.getTime());
  need.setUTCFullYear(need.getUTCFullYear() - years);
  if (!earliest) {
    problems.push({ kind: "no_history", text: `No dated home addresses yet. Applications usually ask where you have lived for the last ${years} years.` });
  } else if (earliest > need) {
    const short = Math.round((earliest - need) / DAY);
    problems.push({ kind: "too_short", days: short,
      text: `Where you lived starts ${ymd(earliest)}, which is ${short} day${short === 1 ? "" : "s"} short of the ${years} years applications usually ask for.` });
  }

  return problems;
}

/**
 * One sentence for the section header: what to fix in where you lived, or
 * that it is ready. Work addresses never change it.
 */
export function historySummary(rows = [], opts = {}) {
  const problems = addressProblems(rows, opts);
  const years = opts.years ?? DEFAULT_LOOKBACK_YEARS;
  if (!problems.length) {
    return { ok: true, text: `Where you lived is unbroken for the last ${years} years. Ready to copy onto an application.` };
  }
  const gaps = problems.filter((p) => p.kind === "gap").length;
  const lead = gaps
    ? `${gaps} gap${gaps === 1 ? "" : "s"} in where you lived`
    : problems[0].text;
  return { ok: false, text: gaps ? `${lead}. An application will be returned for this.` : lead, problems };
}
